tape( 'the method throws an error if provided an index argument which is out-of-bounds (64-bit unsigned integer)', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Uint64Array( 10 );

	values = [
		arr.length,
		arr.length + 1,
		arr.length + 2,
		arr.length + 3
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), RangeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.set( new Uint64( 1 ), value );
		};
	}
});

