tape( 'the method sets an array element (array-like object containing 64-bit unsigned integers)', function test( t ) {
	var expected1;
	var expected2;
	var expected;
	var arr;
	var u1;
	var u2;
	var v;
	var u;
	var i;

	arr = new Uint64Array( 10 );

	v = arr.get( 0 ).valueOf();
	expected = new Uint64( 0 ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	// No index argument:
	u = new Uint64( 20 );
	arr.set( [ u ] );

	expected = u.valueOf();
	v = arr.get( 0 ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	arr.set( [ new Uint64( 0 ) ] );

	// Index argument:
	for ( i = 0; i < arr.length; i++ ) {
		v = arr.get( i ).valueOf();
		expected = new Uint64( 0 ).valueOf();
		t.strictEqual( v, expected, 'returns expected value for index '+i );

		u = new Uint64( i );
		arr.set( [ u ], i );

		v = arr.get( i ).valueOf();
		expected = u.valueOf();
		t.strictEqual( v, expected, 'returns expected value for index '+i );
	}

	// Multiple values, no index argument:
	u1 = new Uint64( 10 );
	u2 = new Uint64( 40 );

	arr.set( [ u1, u2 ] );

	v = arr.get( 0 ).valueOf();
	expected1 = u1.valueOf();
	t.strictEqual( v, expected1, 'returns expected value for index '+0 );

	v = arr.get( 1 ).valueOf();
	expected2 = u2.valueOf();
	t.strictEqual( v, expected2, 'returns expected value for index '+1 );

	// Multiple values, index argument:
	u1 = new Uint64( 100 );
	u2 = new Uint64( 300 );

	arr.set( [ u1, u2 ], 2 );

	v = arr.get( 2 ).valueOf();
	expected1 = u1.valueOf();
	t.strictEqual( v, expected1, 'returns expected value for index '+2 );

	v = arr.get( 3 ).valueOf();
	expected2 = u2.valueOf();
	t.strictEqual( v, expected2, 'returns expected value for index '+3 );

	t.end();
});

tape( 'the method sets an array element (typed array; shared buffer)', function test( t ) {
	var byteOffset;
	var expected;
	var arr;
	var src;
	var buf;
	var ab;
	var v;

	byteOffset = 224;

	ab = new ArrayBuffer( 480 );
	arr = new Uint64Array( ab, byteOffset, 10 );

	// Overlapping (requires copy), multiple values, no index argument:
	buf = [ 20, 30 ];
	src = new Float64Array( ab, byteOffset-(1*arr.BYTES_PER_ELEMENT), 2 );
	src.set( buf );
	arr.set( src );

	v = arr.get( 0 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 1 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	// Overlapping (requires copy), multiple values, index argument:
	buf = [ 100, 200 ];
	src = new Float64Array( ab, byteOffset+(1*arr.BYTES_PER_ELEMENT), 2 );
	src.set( buf );
	arr.set( src, 2 );

	v = arr.get( 2 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+2 );

	v = arr.get( 3 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	// Overlapping (no copy), multiple values, no index argument:
	buf = [ 25, 45 ];
	src = new Float64Array( ab, byteOffset+(1*arr.BYTES_PER_ELEMENT), 2 );
	src.set( buf );
	arr.set( src );

	v = arr.get( 0 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 1 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	// Overlapping (no copy), multiple values, index argument:
	buf = [ 105, 205 ];
	src = new Float64Array( ab, byteOffset+(3*arr.BYTES_PER_ELEMENT), 2 );
	src.set( buf );
	arr.set( src, 2 );

	v = arr.get( 2 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+2 );

	v = arr.get( 3 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+3 );

	t.end();
});

tape( 'the method sets an array element (64-bit unsigned integer typed array; shared buffer)', function test( t ) {
	var byteOffset;
	var expected;
	var arr;
	var src;
	var buf;
	var ab;
	var v;

	byteOffset = 224;

	ab = new ArrayBuffer( 480 );
	arr = new Uint64Array( ab, byteOffset, 10 );

	// Overlapping (requires copy), multiple values, no index argument:
	buf = [ 20, 30 ];
	src = new Uint64Array( ab, byteOffset-(1*arr.BYTES_PER_ELEMENT), 2 );
	src.set( buf );
	arr.set( src );

	v = arr.get( 0 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 1 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	// Overlapping (requires copy), multiple values, index argument:
	buf = [ 100, 200, 300, 400 ];
	src = new Uint64Array( ab, byteOffset+(1*arr.BYTES_PER_ELEMENT), 4 );
	src.set( buf );
	arr.set( src, 2 );

	v = arr.get( 2 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 3 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	v = arr.get( 4 ).valueOf();
	expected = new Uint64( buf[ 2 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+2 );

	v = arr.get( 5 ).valueOf();
	expected = new Uint64( buf[ 3 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+3 );

	// Overlapping (no copy), multiple values, no index argument:
	buf = [ 25, 35, 45, 55 ];
	src = new Uint64Array( ab, byteOffset+(1*arr.BYTES_PER_ELEMENT), 4 );
	src.set( buf );
	arr.set( src );

	v = arr.get( 0 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 1 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	// Overlapping (no copy), multiple values, index argument:
	buf = [ 105, 205, 305, 405 ];
	src = new Uint64Array( ab, byteOffset+(3*arr.BYTES_PER_ELEMENT), 4 );
	src.set( buf );
	arr.set( src, 2 );

	v = arr.get( 2 ).valueOf();
	expected = new Uint64( buf[ 0 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+0 );

	v = arr.get( 3 ).valueOf();
	expected = new Uint64( buf[ 1 ] ).valueOf();
	t.strictEqual( v, expected, 'returns expected value for index '+1 );

	t.end();
});
